package org.marketreview.nativeapp;
import org.json.*;
import java.io.File;
import java.nio.file.Files;
import java.nio.charset.StandardCharsets;
final class SectorResearchChecks {
 interface Work{void run()throws Exception;}
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static void refuses(Work w)throws Exception{boolean failed=false;try{w.run();}catch(Exception e){failed=true;}check(failed,"expected refusal");}
 static JSONObject scope()throws Exception{return new JSONObject().put("kind","sector").put("id","eastmoney:industry:BK0475").put("name","银行").put("source","本机缓存").put("asOf","2000-01-01").put("snapshot",new JSONObject().put("available",false));}
 static final String ARTIFACT="{\"schema\":\"webstock.market-hotspots/v1\",\"payload\":{\"summary\":\"完整摘要\",\"items\":[{\"name\":\"银行\",\"thesis\":\"原始逻辑\",\"risks\":[\"风险\"],\"evidenceRefs\":[\"https://example.com/evidence?id=public\"],\"relatedCodes\":[\"000001\"]}]}}";
 static JSONObject model()throws Exception{JSONObject p=SectorResearchModel.packet(scope(),new JSONArray(),"人工材料完整原文","持续性与风险"),r=SectorResearchModel.result(p,"WEBSTOCK_HOT_MARKET_ANALYSIS_START\n完整报告\nWEBSTOCK_HOT_MARKET_ANALYSIS_END"),a=SectorResearchModel.decode(ARTIFACT).getJSONObject(0);check(p.getString("prompt").contains("月度")&&r.getString("text").equals("完整报告"),"actual manual old marker");refuses(()->SectorResearchModel.result(p,"WEBSTOCK_HOT_MARKET_ANALYSIS_START\nmissing end"));refuses(()->SectorResearchModel.result(p,new JSONObject().put("schema","sector-research-return-v1").put("packetId","wrong").put("scopeId",scope().getString("id")).put("report","wrong").toString()));JSONObject forged=new JSONObject(SectorResearchModel.json(a)).put("rows",new JSONArray());refuses(()->SectorResearchModel.validate(forged));check(a.getJSONArray("rows").getJSONObject(0).getJSONArray("evidenceRefs").getString(0).endsWith("?id=public"),"public query preserved");refuses(()->SectorResearchModel.decode(ARTIFACT.replace("?id=public","?token=secret")));JSONObject review=SectorResearchModel.review(a,0,"SZ:stock:000001","平安银行",new JSONArray().put(new JSONObject().put("id","SZ:stock:000001").put("name","平安银行")));SectorResearchModel.validate(review);refuses(()->SectorResearchModel.review(a,0,"SH:stock:600000","浦发银行",new JSONArray()));refuses(()->SectorResearchModel.review(a,0,"SZ:stock:000001","错名",new JSONArray().put(new JSONObject().put("id","SZ:stock:000001").put("name","平安银行"))));refuses(()->SectorResearchModel.decode("{\"schema\":\"sector-research-v1\",\"records\":[{\"kind\":\"private\",\"id\":\"state\"}]}")); JSONObject pick=new JSONObject().put("kind","research-picks").put("schema","webstock.research-picks/v1").put("payload",new JSONObject().put("picks",new JSONArray().put(new JSONObject().put("code","000001").put("name","平安银行").put("thesis","逻辑").put("risks",new JSONArray().put("风险")).put("evidenceRefs",new JSONArray().put("https://example.com/stock?id=1")))));JSONObject hotspot=new JSONObject(ARTIFACT).put("kind","market-hotspots");JSONObject batch=new JSONObject().put("schema","webstock.external-research-batch/v1").put("automaticTrading",false).put("revision",1).put("source",new JSONObject().put("system","manual").put("taskId","task").put("runId","run").put("generatedAt","2000-01-01T00:00:00Z")).put("asOf",new JSONObject().put("marketDate","2000-01-01").put("observedAt","2000-01-01T00:00:00Z").put("timezone","Asia/Shanghai")).put("artifacts",new JSONArray().put(pick).put(hotspot)).put("deliveries",new JSONArray().put(new JSONObject().put("target","webstock-research")));check(SectorResearchModel.decode(batch.toString()).getJSONObject(0).getJSONObject("original").getJSONObject("batchOriginal").getJSONArray("artifacts").length()==2,"full batch preserved but no picks delivery executed");refuses(()->SectorResearchModel.decode(new JSONObject(batch.toString()).put("automaticTrading",true).toString()));JSONObject chain=new JSONObject("{\"schema\":\"webstock.industry-chain-updates/v1\",\"payload\":{\"chains\":[{\"name\":\"产业\",\"thesis\":\"逻辑\",\"stages\":[\"环节\"],\"catalysts\":[],\"risks\":[\"风险\"],\"evidenceRefs\":[\"https://example.com/chain\"]}]}}");check(SectorResearchModel.decode(chain.toString()).length()==1,"actual old optional catalysts");
 return new JSONObject().put("schema","sector-research-v1").put("records",new JSONArray().put(p).put(r).put(a).put(review));}
 public static void main(String[] args)throws Exception{JSONObject o=model();if(args.length>0)Files.write(new File(args[0]).toPath(),SectorResearchModel.json(o).getBytes(StandardCharsets.UTF_8));System.out.println("PASS SectorResearch production Java old artifact/public query/manual markers/mismatched packet/identity/name/private rejection; model only");}
 static void run(FlowInstrumentation f)throws Exception{JSONObject o=model();File file=f.activity.getDatabasePath("sector-research-checks-"+System.nanoTime()+".sqlite");SectorResearchStore s=new SectorResearchStore(file);JSONObject preview=s.preview(SectorResearchModel.json(o));check(s.list("packets").length()==0,"preview readonly");s.merge(preview);check(s.list("reviews").length()==1,"candidate history");String revision=s.saveState(new JSONObject().put("input","recoverable draft").put("pending",preview),"");refuses(()->s.saveState(new JSONObject(),"stale"));check(s.state().getString("revision").equals(revision),"CAS retains state");SectorResearchStore copy=new SectorResearchStore(f.activity.getDatabasePath("sector-research-copy-"+System.nanoTime()+".sqlite"));copy.merge(copy.preview(s.backup()));check(copy.list("results").length()==1&&copy.state().length()==0,"approved backup excludes drafts");String large="材料原文".repeat(240000);s.saveState(new JSONObject().put("input",large),revision);check(s.state().getString("input").equals(large),"large state crosses CursorWindow without truncation");JSONObject largePacket=SectorResearchModel.packet(scope(),new JSONArray(),large,"风险");s.put(largePacket);check(s.list("packets").getJSONObject(0).getString("manual").equals(large),"large captured record chunk read");s.put(largePacket);s.saveState(new JSONObject().put("input","recoverable draft").put("pending",preview),s.state().getString("revision"));f.ui(()->{try{SectorResearchScreen screen=new SectorResearchScreen(f.activity,f.activity.businessStore,file,()->new JSONArray().put(scope()),()->new JSONArray(),null,null);check(screen.selectScope("sector",scope().getString("id"))&&!screen.selectScope("industry","missing"),"exact scope selection");check(screen.input.getText().toString().equals("recoverable draft")&&screen.pending.getJSONArray("records").length()==4,"recreation retains draft/preview");screen.setDarkTheme(true);check(!screen.back(),"inline complete reading main back");}catch(Exception e){throw new RuntimeException(e);}});}
}


